//! 🧪️ A normal worker returns its original receipt before lending both complete refusal owners.
use semio_framework_job::*;
use semio_framework_job_worker::*;
use semio_framework_job_worker_authority::{BatchDriveConfig,BatchJobParams};
use semio_framework_test_fixtures::fixture_text;
use semio_framework_value::{ValueError,ValueRefusalKind};
use std::mem::ManuallyDrop;
#[global_allocator]
static ORIGINAL_WORKER_HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;

struct OriginalPairedFailureJob{failure:ManuallyDrop<Option<OriginalTurnFailure>>,closing:bool}
impl InteractiveJob for OriginalPairedFailureJob{
 fn step<'a>(&'a mut self,cx:&mut StepContext<'_>)->Result<Option<JobOutcomeBorrow<'a>>,OriginalTurnFailure>{let failure=self.failure.take().expect("one original normal failure");cx.consume_retained(RetainedCloneProgress{copied_items:1,..Default::default()})?;cx.consume_fuel(1);Err(failure)}
 fn borrow_outcome<'a>(&'a self,descriptor:&'a JobOutcomeDescriptor)->Result<JobOutcomeView<'a>,ValueError>{descriptor.complete(None,None)}
 fn begin_close(&mut self){self.closing=true;}
 fn close_step(&mut self,_:&mut StepContext<'_>)->Result<InteractiveJobCloseStep,OriginalTurnFailure>{assert!(self.failure.is_none());Ok(InteractiveJobCloseStep::Complete{progress:Default::default()})}
 fn terminal_is_empty(&self)->bool{self.closing&&self.failure.is_none()}
 fn next_close_copy_byte_demand(&self)->Result<usize,ValueError>{Ok(0)}
 fn next_close_capacity_byte_demand(&self,_:usize)->Result<usize,ValueError>{Ok(0)}
 fn next_close_release_byte_demand(&self)->Result<usize,ValueError>{Ok(0)}
 fn next_close_depth_demand(&self)->Result<usize,ValueError>{Ok(1)}
}
impl Drop for OriginalPairedFailureJob{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original failed job requires paid source return");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.failure)}}}}
fn observed<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
fn clock()->Option<u64>{Some(1000)}

#[test]
fn original_normal_worker_failure_loans_both_causes_after_receipt_and_paid_close(){
 let law:serde_json::Value=serde_json::from_str(fixture_text!("../../⚠️failure/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let source:RetainedCloneGrant=serde_json::from_value(law["source"].clone()).unwrap();let stock:RetainedCloneGrant=serde_json::from_value(law["initialStock"].clone()).unwrap();let work:RetainedCloneGrant=serde_json::from_value(law["work"].clone()).unwrap();let close:RetainedCloneGrant=serde_json::from_value(law["close"].clone()).unwrap();let session_close:RetainedCloneGrant=serde_json::from_value(law["sessionClose"].clone()).unwrap();let(operation,generation)=(OperationId(law["operation"].as_u64().unwrap()),Generation(law["generation"].as_u64().unwrap()));let(mut caller,heap)=observed(||OriginalJobFixtureCaller::admit(operation,generation,stock,clock,law["deadline"].as_u64().unwrap(),law["initialFuel"].as_u64().unwrap()));let mut born=heap.0;assert_eq!(law["clock"],1000);
 let primary=law["primary"].as_str().unwrap();let secondary=law["receiptRefusal"].as_str().unwrap();let bytes=primary.len()+secondary.len();let((failure,pointers),heap)=observed(||caller.turn(source,|cx|{assert!(cx.retained_grant().maximum_copy_bytes>=bytes&&cx.retained_grant().maximum_capacity_bytes>=bytes);let primary=ValueError::new(ValueRefusalKind::UnsupportedOwner,String::from(primary));let secondary=ValueError::new(ValueRefusalKind::InvariantViolated,String::from(secondary));let pointers=(primary.message.as_ptr(),secondary.message.as_ptr());cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,retained_capacity_bytes:bytes,released_bytes:0})?;cx.consume_fuel(1);Ok(({let original=OriginalTurnFailure::from(primary);OriginalTurnFailure{receipt_refusal:Some(secondary),context_refusal:None,..original}},pointers))}).unwrap());assert_eq!(heap,(caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes));born+=heap.0;
 let mut job=Some(OriginalPairedFailureJob{failure:ManuallyDrop::new(Some(failure)),closing:false});let mut params=Some(BatchJobParams{operation,generation,cancel:caller.admit_alias(source),config:BatchDriveConfig{retained:work,site:"original-normal-worker-full-failure",stage:InteractiveStage::InteractiveStep,fuel_per_step:law["fuel"].as_u64().unwrap(),step_budget_us:500},now_us:clock});let demand=WorkerJobSession::<OriginalPairedFailureJob>::owned_admission_demand().unwrap();assert!(demand.copy_bytes>source.maximum_copy_bytes);let(denied,heap)=observed(||caller.turn(source,|cx|MountedWorkerJobSession::try_admit_owned(&mut job,&mut params,cx).map_err(OriginalTurnFailure::from)).unwrap());assert!(denied.is_none());assert_eq!(heap,(0,0));assert_eq!(caller.receipt(),Default::default());assert!(job.is_some()&&params.is_some());let admission=RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes,..source};assert!(admission.maximum_copy_bytes<=caller.remaining_grant().maximum_copy_bytes);let((mut session,receipt),heap)=observed(||caller.turn(admission,|cx|MountedWorkerJobSession::try_admit_owned(&mut job,&mut params,cx).map_err(OriginalTurnFailure::from)).unwrap().expect("fixed original admission policy"));assert_eq!(receipt,caller.receipt());assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));assert!(job.is_none()&&params.is_none());born+=heap.0;
 let(answer,heap)=observed(||caller.turn(work,|cx|cx.with_original_work_loan(law["fuel"].as_u64().unwrap(),law["deadline"].as_u64().unwrap(),|cx|session.pump_one_for_interactive_turn(cx))));let failure=answer.unwrap_err();assert_eq!(heap,(0,0));assert_eq!(caller.receipt(),RetainedCloneProgress{copied_items:1,..Default::default()});assert!(session.checked_out_failure().is_none());assert!(session.take_checked_out_retained_step_receipt().is_none());assert_eq!((failure.primary.message().as_ptr(),failure.receipt_refusal.as_ref().unwrap().message.as_ptr()),pointers);assert_eq!(failure.primary.message(),primary);assert_eq!(failure.receipt_refusal.as_ref().unwrap().message.as_ref(),secondary);assert!(failure.context_refusal.is_none());
 let((mut failure_owner,birth),heap)=observed(||caller.turn(source,|cx|{let(owner,birth)=semio_framework_value::retirement::admit_owned_retirement(failure,cx.retained_grant()).ok().unwrap();cx.consume_retained(birth)?;cx.consume_fuel(1);Ok((owner,birth))}).unwrap());assert_eq!(heap,(birth.retained_capacity_bytes,birth.released_bytes));born+=heap.0;let mut released=heap.1;
 for turn in 0..1024{if failure_owner.terminal_is_empty(){break}let(step,heap)=observed(||caller.turn(close,|cx|{let step=failure_owner.close_step(cx.retained_grant())?;cx.consume_retained(step.progress())?;cx.consume_fuel(1);Ok(step)}).unwrap());assert_eq!(step.progress(),caller.receipt());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.0;released+=heap.1;assert!(turn<1023);}assert!(failure_owner.terminal_is_empty());let frame=birth.retained_capacity_bytes;let(answer,heap)=observed(||caller.turn(close,|cx|{let progress=RetainedCloneProgress{copied_items:1,released_bytes:frame,..Default::default()};assert!(progress.fits(cx.retained_grant()));drop(failure_owner);cx.consume_retained(progress)?;cx.consume_fuel(1);Ok(())}));answer.unwrap();assert_eq!(heap,(0,frame));released+=heap.1;
 session.begin_close();for turn in 0..256{if session.terminal_is_empty(){break}let phase=session.close_phase();let demand=session.retirement_demands(session_close.maximum_copy_bytes).unwrap();let(step,heap)=observed(||caller.close_owner(session_close,&mut session).unwrap());assert_eq!(step.progress().copied_bytes,demand.copy_bytes);assert_eq!(step.progress(),caller.receipt());assert!(step.progress().fits(session_close));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.0;released+=heap.1;assert!(turn<255);}assert!(session.terminal_is_empty());assert_eq!(observed(||drop(session)).1,(0,0));for turn in 0..64{if caller.terminal_is_empty(){break}let(step,heap)=observed(||caller.retire_step(close).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.0;released+=heap.1;assert!(turn<63);}assert!(caller.terminal_is_empty());let total=caller.cumulative_receipt();assert_eq!((born,released),(total.retained_capacity_bytes,total.released_bytes));assert_eq!(born,released);assert_eq!(observed(||drop(caller)).1,(0,0));
}
